def transform(grid):
    h, w = len(grid), len(grid[0])
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 0]
    out = [row[:] for row in grid]
    if len(points) < 3:
        return out

    # Convex hull of the marked cells, using (column, row) coordinates.
    pts = sorted(set((c, r) for r, c in points))

    def cross(o, a, b):
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    lower = []
    for p in pts:
        while len(lower) >= 2 and cross(lower[-2], lower[-1], p) <= 0:
            lower.pop()
        lower.append(p)
    upper = []
    for p in reversed(pts):
        while len(upper) >= 2 and cross(upper[-2], upper[-1], p) <= 0:
            upper.pop()
        upper.append(p)
    hull = lower[:-1] + upper[:-1]
    if len(hull) < 3:
        return out

    for r in range(h):
        for c in range(w):
            inside = True
            p = (c, r)
            for i in range(len(hull)):
                if cross(hull[i], hull[(i + 1) % len(hull)], p) < 0:
                    inside = False
                    break
            if inside and grid[r][c] != 0:
                out[r][c] = 3
    return out
